// State
        let currentThreshold = 20; // ms
        let soundEnabled = true;
        let totalStrokes = 0;
        let cleanStrokes = 0;
        let chatterFaults = 0;
        const keyHistory = new Map(); // code -> { lastDown, lastUp, totalPresses, chatterCount }
        const faultLog = [];
        let audioCtx = null;

        // Elements
        const captureZone = document.getElementById('test-capture-zone');
        const matrixGrid = document.getElementById('key-matrix-grid');
        const logContainer = document.getElementById('event-log-container');
        const statTotal = document.getElementById('stat-total');
        const statClean = document.getElementById('stat-clean');
        const statFaults = document.getElementById('stat-faults');
        const statHealth = document.getElementById('stat-health');
        const statusDot = document.getElementById('status-dot');
        const statusText = document.getElementById('status-text');

        // Web Audio Synthesizer
        function initAudio() {
            if (!audioCtx) {
                const AudioClass = window.AudioContext || window.webkitAudioContext;
                if (AudioClass) audioCtx = new AudioClass();
            }
            if (audioCtx && audioCtx.state === 'suspended') {
                audioCtx.resume().catch(() => {});
            }
        }

        function playKeystrokeTone(isFault) {
            if (!soundEnabled) return;
            try {
                initAudio();
                if (!audioCtx) return;
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                const now = audioCtx.currentTime;

                if (isFault) {
                    // Warning buzzer tone
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(180, now);
                    osc.frequency.exponentialRampToValueAtTime(120, now + 0.12);
                    gain.gain.setValueAtTime(0.18, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
                    osc.connect(gain);
                    gain.connect(audioCtx.destination);
                    osc.start(now);
                    osc.stop(now + 0.12);
                } else {
                    // Crisp mechanical click
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(750, now);
                    gain.gain.setValueAtTime(0.06, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.035);
                    osc.connect(gain);
                    gain.connect(audioCtx.destination);
                    osc.start(now);
                    osc.stop(now + 0.035);
                }
            } catch (e) {}
        }

        function toggleAudioFeedback() {
            soundEnabled = !soundEnabled;
            const icon = document.getElementById('sound-icon');
            const text = document.getElementById('sound-text');
            if (icon) {
                icon.innerHTML = soundEnabled 
                    ? `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z"></path></svg>`
                    : `<svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2"></path></svg>`;
            }
            if (text) text.innerText = soundEnabled ? 'Sound ON' : 'Sound OFF';
        }

        function setThreshold(ms) {
            currentThreshold = ms;
            const label = document.getElementById('current-threshold-label');
            if (label) {
                const desc = ms === 10 ? 'Optical / Hall' : ms === 20 ? 'Speed Linear' : ms === 30 ? 'Standard MX' : 'Strict Anti-Chatter';
                label.innerText = `${ms} ms (${desc})`;
            }
            document.querySelectorAll('.threshold-btn').forEach(btn => {
                const t = parseInt(btn.getAttribute('data-threshold'));
                if (t === ms) {
                    btn.className = 'threshold-btn px-3 py-2 rounded-xl text-xs font-bold transition border bg-indigo-600 border-indigo-600 text-white shadow-sm';
                    btn.querySelector('span').className = 'block text-[9px] font-normal text-indigo-100';
                } else {
                    btn.className = 'threshold-btn px-3 py-2 rounded-xl text-xs font-bold transition border bg-white border-slate-200 text-slate-600 hover:border-indigo-400';
                    btn.querySelector('span').className = 'block text-[9px] font-normal text-slate-400';
                }
            });
            appendLog(`[Config] Debounce threshold changed to ${ms}ms.`);
        }

        function updateStats() {
            statTotal.innerText = totalStrokes.toLocaleString();
            statClean.innerText = cleanStrokes.toLocaleString();
            statFaults.innerText = chatterFaults.toLocaleString();
            const pct = totalStrokes > 0 ? ((cleanStrokes / totalStrokes) * 100).toFixed(1) : '100.0';
            statHealth.innerText = `${pct}%`;
            if (chatterFaults > 0) {
                statHealth.className = 'text-2xl font-black text-red-600 font-mono';
            } else {
                statHealth.className = 'text-2xl font-black text-indigo-700 font-mono';
            }
        }

        function appendLog(html) {
            const row = document.createElement('div');
            row.innerHTML = html;
            logContainer.appendChild(row);
            logContainer.scrollTop = logContainer.scrollHeight;
        }

        function getOrCreateKeyCap(code, keyLabel) {
            let cap = document.getElementById(`cap-${code}`);
            if (!cap) {
                if (matrixGrid.querySelector('.italic')) {
                    matrixGrid.innerHTML = '';
                }
                cap = document.createElement('div');
                cap.id = `cap-${code}`;
                cap.className = 'key-cap px-2.5 py-1.5 rounded-lg border text-xs font-mono font-bold bg-white border-slate-300 text-slate-700 shadow-sm flex items-center gap-1.5';
                cap.innerHTML = `<span>${keyLabel}</span><span id="badge-${code}" class="text-[9px] px-1 rounded bg-slate-100 text-slate-400">0</span>`;
                matrixGrid.appendChild(cap);
            }
            return cap;
        }

        function handleKeyDown(e) {
            // Prevent scrolling on space or navigation in test area
            if (['Space', 'ArrowUp', 'ArrowDown', 'PageUp', 'PageDown'].includes(e.code) && document.activeElement === captureZone) {
                e.preventDefault();
            }

            const now = performance.now();
            const code = e.code || e.key;
            const displayKey = e.key === ' ' ? 'Space' : e.key.length === 1 ? e.key.toUpperCase() : e.key;

            let record = keyHistory.get(code);
            if (!record) {
                record = { lastDown: 0, lastUp: 0, totalPresses: 0, chatterCount: 0 };
                keyHistory.set(code, record);
            }

            const deltaDown = record.lastDown > 0 ? (now - record.lastDown) : 9999;
            const deltaUp = record.lastUp > 0 ? (now - record.lastUp) : 9999;
            const minDelta = Math.min(deltaDown, deltaUp);

            record.totalPresses++;
            totalStrokes++;

            const cap = getOrCreateKeyCap(code, displayKey);
            cap.classList.add('pressed');

            let isFault = false;
            // Check if key repeat is browser-synthetic or physical contact bounce
            if (!e.repeat && minDelta < currentThreshold && minDelta > 0.5) {
                // CHATTER DETECTED!
                isFault = true;
                chatterFaults++;
                record.chatterCount++;
                cap.classList.add('chattered');
                cap.classList.remove('clean');

                faultLog.push({
                    timestamp: new Date().toLocaleTimeString(),
                    code: code,
                    key: displayKey,
                    deltaMs: minDelta.toFixed(1),
                    threshold: currentThreshold
                });

                appendLog(`<span class="text-red-400 font-bold">[FAULT]</span> Key "${displayKey}" chattered! Double-hit in <span class="text-red-300 font-bold">${minDelta.toFixed(1)}ms</span> (&lt; ${currentThreshold}ms).`);
                playKeystrokeTone(true);
            } else {
                cleanStrokes++;
                if (record.chatterCount === 0) {
                    cap.classList.add('clean');
                }
                playKeystrokeTone(false);
                appendLog(`<span class="text-emerald-400 font-bold">[OK]</span> Key "${displayKey}" registered. Delta: ${minDelta === 9999 ? '--' : minDelta.toFixed(1) + 'ms'}.`);
            }

            const badge = document.getElementById(`badge-${code}`);
            if (badge) {
                if (record.chatterCount > 0) {
                    badge.innerText = `x${record.chatterCount} ERR`;
                    badge.className = 'text-[9px] px-1 rounded bg-red-100 text-red-700 font-black';
                } else {
                    badge.innerText = `${record.totalPresses}`;
                    badge.className = 'text-[9px] px-1 rounded bg-emerald-100 text-emerald-700';
                }
            }

            record.lastDown = now;
            updateStats();
        }

        function handleKeyUp(e) {
            const now = performance.now();
            const code = e.code || e.key;
            const cap = document.getElementById(`cap-${code}`);
            if (cap) {
                cap.classList.remove('pressed');
            }
            const record = keyHistory.get(code);
            if (record) {
                record.lastUp = now;
            }
        }

        function resetDiagnostics() {
            totalStrokes = 0;
            cleanStrokes = 0;
            chatterFaults = 0;
            keyHistory.clear();
            faultLog.length = 0;
            updateStats();
            matrixGrid.innerHTML = '<div class="text-xs text-slate-400 italic p-2 text-center w-full">Type any key above to populate the switch diagnostic matrix.</div>';
            logContainer.innerHTML = '<div class="text-slate-500 italic">[0.000s] Reset complete. Awaiting hardware switch contacts...</div>';
            if (statusDot) statusDot.className = 'w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]';
            if (statusText) statusText.innerText = 'Listening for Keystrokes';
        }

        function copyDiagnosticReport() {
            const healthScore = totalStrokes > 0 ? ((cleanStrokes / totalStrokes) * 100).toFixed(1) : '100.0';
            const faultyKeys = Array.from(keyHistory.entries())
                .filter(([_, v]) => v.chatterCount > 0)
                .map(([k, v]) => `  - ${k}: ${v.chatterCount} bounce faults (${v.totalPresses} total presses)`)
                .join('\n');

            const report = `=== ToolkitGen Mechanical Keyboard Chatter Diagnostic Report ===\n` +
                `Date: ${new Date().toLocaleString()}\n` +
                `Debounce Threshold: ${currentThreshold} ms\n` +
                `Total Keystrokes: ${totalStrokes}\n` +
                `Clean Actuations: ${cleanStrokes}\n` +
                `Chatter Faults: ${chatterFaults}\n` +
                `Switch Health: ${healthScore}%\n` +
                `Faulty Keys Detected:\n${faultyKeys || '  None (0 faulty switches detected)'}\n` +
                `Diagnostic Tool: https://toolkitgen.com/tool/keyboard_chatter_detector`;

            if (navigator.clipboard) {
                navigator.clipboard.writeText(report).then(() => {
                    alert("Diagnostic report copied to clipboard! You can paste this directly into warranty tickets.");
                }).catch(() => prompt("Copy your RMA report:", report));
            } else {
                prompt("Copy your RMA report:", report);
            }
        }

        // Event Listeners
        window.addEventListener('keydown', (e) => {
            // If typing in another input (like search), ignore
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
            handleKeyDown(e);
        });

        window.addEventListener('keyup', (e) => {
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
            handleKeyUp(e);
        });

        captureZone.addEventListener('click', () => {
            captureZone.focus();
            initAudio();
        });
